//! `doctor::inspect` (lot 6.2) where the command line cannot reach, against the reports of the
//! real `InstanceDoctor` (`rust/tests/golden/doctor.json`, regenerated by
//! `rust/tools/doctor-oracle`): without the probes of the CLI, and with an injected ownership
//! that sees an entry of another account (`ForeignOwnership` of `HardeningTests`) or cannot read
//! the owner. The version of SQLite in the `sqlite` check is the one of each engine (decision A6).

use std::fs;
use std::io;
use std::path::{Path, PathBuf};

use serde_json::Value;
use sermofur_core::doctor::inspect;
use sermofur_core::init::initialize;
use sermofur_core::ownership::{EntryStatus, FileOwnership, SystemOwnership};
use sermofur_core::records::write;
use uuid::Uuid;

/// The temporary directory as the oracle's `TestInstance.TempRoot` sees it: links resolved, since
/// on macOS `/var` is a link to `/private/var` and the store refuses links on every ancestor.
/// Windows keeps `temp_dir` as is (`canonicalize` would add the `\\?\` prefix).
fn temp_base() -> PathBuf {
    let dir = std::env::temp_dir();
    if cfg!(windows) {
        dir
    } else {
        std::fs::canonicalize(dir).expect("the temporary directory resolves")
    }
}

/// A folder under the temporary directory, removed on drop (doctor closes its store itself).
struct Folder(PathBuf);

impl Drop for Folder {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

struct Foreign;

impl FileOwnership for Foreign {
    fn inspect(&self, path: &Path) -> io::Result<Option<EntryStatus>> {
        Ok(fs::metadata(path).ok().map(|metadata| EntryStatus {
            is_regular_file: metadata.is_file(),
            is_directory: metadata.is_dir(),
            is_owned_by_current_user: false,
        }))
    }
}

struct Unreadable;

impl FileOwnership for Unreadable {
    fn inspect(&self, _path: &Path) -> io::Result<Option<EntryStatus>> {
        Err(io::Error::other("owner unreadable"))
    }
}

#[test]
fn reports_match_the_dotnet_oracle() {
    let golden: Value = serde_json::from_str(
        &fs::read_to_string(
            Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/golden/doctor.json"),
        )
        .expect("golden file"),
    )
    .expect("JSON");
    let cases = golden.as_array().expect("cases");
    assert_eq!(cases.len(), 3);
    for case in cases {
        let name = case["name"].as_str().expect("name");
        let owners: &dyn FileOwnership = match name {
            "without_probes" => &SystemOwnership,
            "foreign_owner" => &Foreign,
            "unreadable_owner" => &Unreadable,
            other => panic!("unknown case {other}"),
        };
        let folder =
            Folder(temp_base().join(format!("sermofur-doctor-{}", Uuid::new_v4().simple())));
        fs::create_dir_all(&folder.0).expect("folder");
        let root = initialize(&folder.0).expect("instance").root;
        let mut report = inspect(&root, owners, None, None).expect("report");
        report.root = "<root>".to_owned();
        let expected = case["report"]
            .as_str()
            .expect("report")
            .replace("Native version 3.53.4;", "Native version 3.53.2;");
        assert_eq!(
            write(&report).expect("JSON").replace("\r\n", "\n"),
            expected,
            "{name}"
        );
    }
}
